import{z as o,x as s,o as l,c as m,q as i,j as r,D as E,d as e,s as A,S as B,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"投机解码与注意力内核的交互","description":"","frontmatter":{"title":"投机解码与注意力内核的交互","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ak-speculative-interaction.md","filePath":"llm/ak-speculative-interaction.md","lastUpdated":1791413859000}'),d={name:"llm/ak-speculative-interaction.md"};function p(c,a,C,h,D,F){const n=s("Mermaid");return l(),m("div",null,[a[2]||(a[2]=i('<h1 id="投机解码与注意力内核的交互" tabindex="-1">投机解码与注意力内核的交互 <a class="header-anchor" href="#投机解码与注意力内核的交互" aria-label="Permalink to &quot;投机解码与注意力内核的交互&quot;">​</a></h1><div class="epigraph"><p>投机解码把 decode 的查询行数从 1 变成 γ+1；内核若还是那个 q=1 的内核，草稿赚到的步数会被一遍遍重复读 KV 全数退还。</p><footer>—— 据 Leviathan et al., 2023；vLLM / FlashInfer 实现口径整理</footer></div><p><a href="/llm/ak-quantized-attention-kernel">上一课</a>收掉变体单元，工程化单元从系统交互开始。<a href="/llm/speculative-decoding">投机解码原理</a>在算法侧定过提议、校验与接受规则；本课只看它与注意力内核的四个接触面：查询行数、掩码形状、KV 写回、批内变长。投机在算法上保分布，内核要保的是不把保真的算法跑成失真、不把省下的步数赔在带宽上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><span class="marginnote">术语翻译：投机解码就是「小快模型先替大模型猜 \\(\\gamma\\) 个词，大模型一次并行批改」——对的留下，错的从错处重来。算法上输出分布不变，赚的是把串行的逐 token 生成压成一次大批改；本课讲的是这笔账怎么别在内核上亏回去。</span>校验一步要对 \\(\\gamma+1\\) 个位置各算注意力：\\(n_q\\) 从 1 变成 \\(\\gamma+1\\)。内核的形状、算术强度与最优配置随之全变。最直接的错法是拿现成的 q=1 解码内核逐 token 调用：同一份 KV 被读 \\(\\gamma+1\\) 遍，而投机赚的恰是「一次 KV 读服务多个 token」这笔带宽账——步数省了，字节翻了，墙钟不赚反赔。反过来把它当成普通前填也不对：网格按长序列的 tile 划分，γ+1 行的小查询填不满流水。缺口是一个专属于「短而宽」形状的内核路径。</p><h3 id="树形草稿改的不是算法是掩码" tabindex="-1">树形草稿改的不是算法是掩码 <a class="header-anchor" href="#树形草稿改的不是算法是掩码" aria-label="Permalink to &quot;树形草稿改的不是算法是掩码&quot;">​</a></h3><p>链式草稿的 \\(\\gamma+1\\) 个位置是普通因果链；<a href="/llm/speculative-tree">树状验证</a>的草稿是树：兄弟分支互不可见。这在数学上只是换一张布尔掩码，在内核上是把「因果掩码」换成「树掩码」传进同一个循环——前提是内核的掩码通道本来就是块级、可换的。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>内核侧三件事。第一，变长 \\(q\\) 接口：接受 \\(n_q=\\gamma+1\\) 的小批查询，网格按行块展开，KV 载入一次、被所有行块复用——骨架就是第一单元的 tiling，只是形状换了。第二，掩码通道参数化：因果掩码与树掩码都作为块级布尔图传入，落在 \\(S\\) 上；接受率统计与位置对齐由外层做，内核只认图。第三，KV 写回与回滚：草稿位置的 KV 在校验时已经算出，被拒绝的尾部要回收——按第 5 课的页表接口就是页引用减一，或者标记惰性失效；接受前缀的 KV 原样保留，下一步直接续用。<span class="marginnote">直觉类比：KV 回滚像用铅笔打草稿——草稿的痕迹（页引用）先记上账，批改后没被采纳的尾部用橡皮擦掉（页引用减一），被采纳的前缀描深定稿、下一步接着写。怕的不是擦，是擦不干净留下的脏数据。</span></p>',9)),(l(),r(B,null,{default:E(()=>[A(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%8D%89%E7%A8%BF%EF%BC%9A%CE%B3%2B1%20%E4%B8%AA%E4%BD%8D%E7%BD%AE%EF%BC%88%E9%93%BE%E6%88%96%E6%A0%91%EF%BC%89%22%5D%20--%3E%20B%5B%22%E5%8F%98%E9%95%BF%20q%20%E5%86%85%E6%A0%B8%EF%BC%9AKV%20%E8%AF%BB%E4%B8%80%E6%AC%A1%22%5D%0A%20%20B%20--%3E%20C%7B%22%E6%A0%91%E5%BD%A2%E8%8D%89%E7%A8%BF%3F%22%7D%0A%20%20C%20--%3E%7C%E6%98%AF%7C%20D%5B%22%E6%A0%91%E6%8E%A9%E7%A0%81%E7%9B%96%E5%9C%A8%20S%20%E5%9D%97%E4%B8%8A%22%5D%0A%20%20C%20--%3E%7C%E5%90%A6%7C%20E%5B%22%E6%99%AE%E9%80%9A%E5%9B%A0%E6%9E%9C%E6%8E%A9%E7%A0%81%22%5D%0A%20%20D%20--%3E%20F%5B%22%E6%8C%89%E4%BC%BC%E7%84%B6%E6%AF%94%E6%8E%A5%E5%8F%97%E5%89%8D%E7%BC%80%22%5D%0A%20%20E%20--%3E%20F%0A%20%20F%20--%3E%20G%5B%22%E6%8E%A5%E5%8F%97%E7%9A%84%20KV%20%E4%BF%9D%E7%95%99%EF%BC%9B%E6%8B%92%E7%BB%9D%E5%B0%BE%E9%83%A8%E5%9B%9E%E6%94%B6%E9%A1%B5%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[e("带宽账要算细：设共要产出 \\(\\tau\\) 个 token，链式草稿下的 KV 全读从 \\(\\tau\\) 次降到约 \\(\\tau/(\\gamma+1)\\) 次——内核一次调用读 KV、服务 \\(\\gamma+1\\) 行，这是投机在系统层赚钱的物理来源；逐 token 调用的实现把这笔账清零。树掩码错成因果掩码的后果比慢更糟：兄弟分支互相可见，草稿间「达成共识」，校验通过率虚高，输出分布已不再等于目标分布——这不是近似误差，是正确性错误，而且静默。"),t("span",{class:"marginnote"},"为什么重要：树掩码错成因果掩码不会报错也不会变慢，只是兄弟分支互相看见、草稿间「串通」，接受率虚高而输出分布悄然偏离目标——像多位考生互相抄了答案再一起交卷。这种静默正确性事故上线后极难察觉。"),e("批内各请求 \\(\\gamma\\) 不同、树形各异时，形状是真正的变长批次，第 5 课的块表加长度表接口原样接住，掩码图按请求传。")],-1)),(l(),r(B,null,{default:E(()=>[A(n,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20V%5B%22%E6%A0%A1%E9%AA%8C%E4%B8%80%E6%AD%A5%EF%BC%9A%CE%B3%2B1%20%E8%A1%8C%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20P1%5B%22%E9%94%99%E6%B3%95%EF%BC%9A%E9%80%90%20token%20%E8%B0%83%E7%94%A8%3Cbr%2F%3EKV%20%E5%85%A8%E8%AF%BB%20%CE%B3%2B1%20%E9%81%8D%22%5D%0A%20%20V%20--%3E%20P2%5B%22%E6%AD%A3%E8%A7%A3%EF%BC%9A%E5%8F%98%E9%95%BF%20q%20%E5%86%85%E6%A0%B8%3Cbr%2F%3EKV%20%E5%85%A8%E8%AF%BB%201%20%E9%81%8D%22%5D%0A%20%20P1%20--%3E%20L%5B%22%E6%AD%A5%E6%95%B0%E7%9C%81%E4%BA%86%E5%AD%97%E8%8A%82%E7%BF%BB%E4%BA%86%3Cbr%2F%3E%E5%A2%99%E9%92%9F%E4%B8%8D%E8%B5%9A%E5%8F%8D%E8%B5%94%22%5D%0A%20%20P2%20--%3E%20W%5B%22KV%20%E8%AF%BB%E6%AC%A1%E6%95%B0%20%C3%B7%20%CE%B3%2B1%3Cbr%2F%3E%E6%8A%95%E6%9C%BA%E6%94%B6%E7%9B%8A%E8%90%BD%E8%A2%8B%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">\\(\\gamma=4\\) 时校验一步 \\(n_q=5\\)：KV 读一遍替代至多五遍；平均接受约 2–3 个 token 时净赚仍在。把五次校验拆成五次 \\(n_q=1\\) 调用的实现，一分钱也赚不到——这是投机解码「无效化」的头号工程原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>接受规则保分布是算法课已证的命题，本课不重证；内核侧的责任是掩码语义与接受前缀一致。草稿模型的 KV 是否入页、占多少配额，是 KV 管理的题目。\\(\\gamma\\) 的动态调整（按接受率伸缩）会改变 \\(n_q\\) 的取值集合，本课只指出后果：形状桶变宽，配置缓存键必须把 \\(n_q\\) 记进去，后面调优一课兑现。多草稿模型与自推测是草稿供给侧的变体，与内核接口无关。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>投机把 decode 变成「短而宽」：变长 \\(q\\) 内核一次读 KV、服务 \\(\\gamma+1\\) 行。</li><li>带宽账是投机的物理来源：KV 全读次数从 \\(\\tau\\) 降到 \\(\\tau/(\\gamma+1)\\)；逐 token 调用清零收益。</li><li>树掩码是块级布尔图，与因果掩码共用通道；错成因果掩码是正确性事故。</li><li>KV 写回按页表回收拒绝尾部，接受前缀原样续用。</li><li>批内变长由块表加长度表接口接住，\\(n_q\\) 必须进配置缓存键。</li><li>出处：Leviathan et al., <em>Fast Inference via Speculative Decoding</em>, 2023；据 vLLM 与 FlashInfer 实现整理。</li></ul>',5))])}const V=o(d,[["render",p]]);export{_ as __pageData,V as default};
